-- Mode controls, daily reminder and voluntary retirement. No scenario/balance changes.
UPDATE game_locale_ui SET ui=json_set(ui, '$.modes', json('{"label":"Режим игры","arcade":{"name":"Аркада","description":"Кресло ваше. Пока не отобрали."},"daily":{"name":"Ежедневный","description":"Дела подождут. Мэр тоже человек."},"blitz":{"name":"Блиц","description":"Заседание идёт. Думать надо было раньше."},"restart":"Смена режима начнёт новый срок с нуля. Продолжить?","pauseDaily":"Ежедневная партия сохранится. Перейти в другой режим?","turns":"Ходы сегодня: {remaining}/5","closed":"Рабочий день в мэрии окончен. Новые дела — завтра.","reminder":"В мэрии ждут: на сегодня осталось ходов — {remaining}. Продолжить ежедневную игру","resign":"Я ухожу в отставку","confirmResign":"Уйти в отставку и завершить текущий срок?","all":"Все режимы","resignations":"Добровольные отставки"}'), '$.titles.resignation', 'Добровольная отставка', '$.titles.resignation_peak', 'Ушёл на пике в Кейсарию', '$.titles.indecision', 'Мэр без решения'), alerts=json_set(alerts, '$.resignation', 'Вы добровольно сложили полномочия. Кресло свободно, офшоры при вас.', '$.indecision', 'Пока вы собирались с мыслями, заседание закончилось. Вместе с вашей карьерой.') WHERE lang='ru';

UPDATE game_locale_ui SET ui=json_set(ui, '$.modes', json('{"label":"Game mode","arcade":{"name":"Arcade","description":"The chair is yours. Until it isn’t."},"daily":{"name":"Daily","description":"The paperwork can wait. Even mayors need a break."},"blitz":{"name":"Blitz","description":"The meeting is underway. Thinking was for earlier."},"restart":"Changing mode starts a new term from scratch. Continue?","pauseDaily":"Your daily game will be saved. Switch to another mode?","turns":"Moves left today: {remaining}/5","closed":"City Hall is closed for the day. Fresh trouble arrives tomorrow.","reminder":"City Hall is waiting: {remaining} moves left today. Continue your daily game","resign":"I resign","confirmResign":"Resign and end your current term?","all":"All modes","resignations":"Voluntary resignations"}'), '$.titles.resignation', 'Voluntary Retirement', '$.titles.resignation_peak', 'Retired to Caesarea at the Top', '$.titles.indecision', 'Mayor of Maybe'), alerts=json_set(alerts, '$.resignation', 'You stepped down voluntarily. The chair is vacant. Your offshore money is still yours.', '$.indecision', 'While you gathered your thoughts, the meeting ended. So did your career.') WHERE lang='en';

UPDATE game_locale_ui SET ui=json_set(ui, '$.modes', json('{"label":"מצב משחק","arcade":{"name":"ארקייד","description":"הכיסא שלך. עד שייקחו אותו."},"daily":{"name":"יומי","description":"הניירת תחכה. גם לראש העיר מגיעה הפסקה."},"blitz":{"name":"בליץ","description":"הישיבה התחילה. היה צריך לחשוב קודם."},"restart":"שינוי מצב המשחק יתחיל כהונה חדשה מאפס. להמשיך?","pauseDaily":"המשחק היומי יישמר. לעבור למצב אחר?","turns":"מהלכים שנותרו היום: {remaining}/5","closed":"יום העבודה בעירייה נגמר. צרות חדשות יגיעו מחר.","reminder":"בעירייה מחכים: נותרו היום {remaining} מהלכים. להמשיך במשחק היומי","resign":"אני מתפטר","confirmResign":"להתפטר ולסיים את הכהונה הנוכחית?","all":"כל המצבים","resignations":"התפטרויות מרצון"}'), '$.titles.resignation', 'פרישה מרצון', '$.titles.resignation_peak', 'פרש בשיא לקיסריה', '$.titles.indecision', 'ראש עיר בלי החלטה'), alerts=json_set(alerts, '$.resignation', 'התפטרת מרצונך. הכיסא פנוי, הכסף בחו״ל נשאר שלך.', '$.indecision', 'בזמן שאספת את המחשבות, הישיבה נגמרה. גם הקריירה שלך.') WHERE lang='he';

UPDATE game_locale_ui SET ui=json_set(ui, '$.modes', json('{"label":"Режим гри","arcade":{"name":"Аркада","description":"Крісло ваше. Поки не забрали."},"daily":{"name":"Щоденний","description":"Справи зачекають. Мер теж людина."},"blitz":{"name":"Бліц","description":"Засідання триває. Думати треба було раніше."},"restart":"Зміна режиму почне новий строк із нуля. Продовжити?","pauseDaily":"Щоденну партію буде збережено. Перейти в інший режим?","turns":"Ходи на сьогодні: {remaining}/5","closed":"Робочий день у мерії скінчився. Нові справи — завтра.","reminder":"У мерії чекають: на сьогодні залишилося ходів — {remaining}. Продовжити щоденну гру","resign":"Я йду у відставку","confirmResign":"Піти у відставку й завершити поточний строк?","all":"Усі режими","resignations":"Добровільні відставки"}'), '$.titles.resignation', 'Добровільна відставка', '$.titles.resignation_peak', 'Пішов на піку до Кейсарії', '$.titles.indecision', 'Мер без рішення'), alerts=json_set(alerts, '$.resignation', 'Ви добровільно склали повноваження. Крісло вільне, офшори залишилися з вами.', '$.indecision', 'Поки ви збиралися з думками, засідання скінчилося. Разом із вашою кар’єрою.') WHERE lang='uk';
